inline double volume(const std::vector<Triangle>&triangles){double value=0;for(auto&t:triangles)value+=storm_ship_hull::dot(t[0].position,storm_ship_hull::cross(t[1].position,t[2].position))/6.;return value;}
inline double ray(const Mesh&m,Vec3 a,Vec3 b){double hit=2;for(auto&o:m)for(auto&t:o.second){const auto u=t[1].position-t[0].position,v=t[2].position-t[0].position,d=b-a,n=storm_ship_hull::cross(u,v);double den=storm_ship_hull::dot(n,d);if(std::abs(den)<1e-10)continue;double f=storm_ship_hull::dot(n,t[0].position-a)/den;if(f<0||f>1||f>=hit)continue;auto p=a+d*float(f);bool in=true;for(int k=0;k<3;++k)in&=storm_ship_hull::dot(storm_ship_hull::cross(t[(k+1)%3].position-t[k].position,p-t[k].position),n)>=-1e-7*storm_ship_hull::dot(n,n);if(in)hit=f;}return hit;}
inline void finish(Projection&p){std::vector<CapTriangle>a;assert(finishCoverage(p,{},a));}
