 std::ifstream file(argv[1]);std::string payload((std::istreambuf_iterator<char>(file)),{});Input input;input.original=std::make_shared<const Mesh>(fixture());input.terrainObjects={0};input.active=true;input.checkpoint=payload;Projection restored;const char*failure=nullptr;if(!prepare(input,restored,&failure)){std::cerr<<failure<<"\n";return 2;}
