 assert(ray(restored.retained,{3,0,0},{3,-4,0})==.5);assert(ray(restored.retained,{.5f,2,-2},{.5f,2,2})==2);assert(std::abs(ray(restored.retained,{-.5f,2,-2},{-.5f,2,2})-.25)<1.e-6);
 std::cout<<"prior-checkpoint terrain draw/collision restored; stone half-volume + exact cap + collision retained PASS\n";
 input.checkpoint=restored.checkpoint;Projection second;assert(prepare(input,second));finish(second);assert(same(second.retained.at(0),restored.retained.at(0)));assert(std::abs(volume(second.retained.at(1))-4.)<1.e-5);std::cout<<"new checkpoint round trip PASS\n";
 input.checkpoint.clear();Cut beam;beam.kind=Cut::Beam;storm_hull_damage::BeamSample sample;sample.start={0,2,-1};sample.direction={0,0,1};sample.depth=.3;beam.beams={sample};beam.field=2;input.cuts={beam};Projection laser;assert(prepare(input,laser));finish(laser);assert(same(laser.retained.at(0),input.original->at(0)));assert(std::abs(ray(laser.retained,{0,2,-2},{0,2,2})-.325)<1.e-6);
 Cut blast;blast.kind=Cut::Sphere;blast.center={0,2,-1};blast.radius=.5;blast.field=3;input.cuts={blast};Projection crater;assert(prepare(input,crater));finish(crater);assert(same(crater.retained.at(0),input.original->at(0)));assert(ray(crater.retained,{0,2,-2},{0,2,2})>.25);std::cout<<"beam/crater stone cuts + unchanged terrain PASS\n";
 Cut ground=beam;ground.beams[0].start={3.5f,-2,0};ground.beams[0].direction={0,-1,0};input.cuts={ground};Projection shore;assert(prepare(input,shore));finish(shore);assert(same(shore.retained.at(0),input.original->at(0)));assert(same(shore.retained.at(1),input.original->at(1)));assert(shore.material->changed.empty());
 GEOM geometry;geometry.object[0].center={0,-2,0};geometry.object[0].radius=6;geometry.object[1].center={0,2,0};assert(!geometry.WorldCutAffects(ground,true));assert(geometry.WorldCutAffects(beam,true));assert(geometry.WorldCutAffects(ground,false));geometry.rhead.nobjects=1;assert(!geometry.WorldCutAffects(ground,true));std::cout<<"source-body terrain-only admission false / mixed stone true / ordinary unclassified stone true PASS\n";
 input.cuts={beam};auto before=shore.retained;input.cuts.front().beams.front().depth=NAN;assert(!prepare(input,shore));assert(same(before.at(0),shore.retained.at(0)));assert(same(before.at(1),shore.retained.at(1)));std::cout<<"invalid dose preserves previous terrain + stone PASS\n";
